mapper.select:


    item_id = #{itemId}
    and type = #{type}
    and create_by = #{createBy}

limit 1

select r.id, r.item_id, r.type, r.del_flag, r.version, r.create_by, r.create_time, r.update_by, r.update_time, r.remark, COALESCE(r.item_name, w.name) as item_name, COALESCE(r.item_thumbnail, w.thumbnail, w.url) as item_thumbnail, COALESCE(w.url, w.thumbnail) as item_url, COALESCE(u.nick_name, CASE WHEN r.create_by LIKE 'fake_like_%' THEN CONCAT('虚拟用户', SUBSTRING(r.create_by, 11)) WHEN r.create_by IS NULL OR r.create_by = '' THEN '游客' END, r.create_by) as create_by_name from px_like_record r left join px_wallpaper w on r.item_id = w.id left join sys_user u on r.create_by = u.user_id
r.type = #{type}
and r.create_by = #{createBy}
order by r.create_time desc

SELECT DATE_FORMAT(r.create_time, '%Y-%m-%d') AS date,
       r.type,
       COUNT(*) AS count
FROM px_like_record r
WHERE r.type = #{likeType}
  AND r.create_time IS NOT NULL

    AND r.create_time >= #{beginTime}


    AND r.create_time <= #{endTime}

GROUP BY DATE_FORMAT(r.create_time, '%Y-%m-%d'), r.type
ORDER BY date

select r.id, r.item_id, r.type, r.del_flag, r.version, r.create_by, r.create_time, r.update_by, r.update_time, r.remark, COALESCE(r.item_name, w.name) as item_name, COALESCE(r.item_thumbnail, w.thumbnail, w.url) as item_thumbnail, COALESCE(w.url, w.thumbnail) as item_url from px_like_record r left join px_wallpaper w on r.item_id = w.id
r.create_by = #{createBy} and r.type = #{type}
order by r.create_time desc
